(function(root){
'use strict';
const base={rentalCents:49900,annualCents:199900};
const codes={QM90:9000,QM80:8000,QM50:5000};
function quote(input={}){const code=String(input.code||'').trim().toUpperCase();if(code&&!Object.hasOwn(codes,code))throw new Error('INVALID_COUPON');const bps=code?codes[code]:10000;const quantity=input.quantity??1;if(!Number.isInteger(quantity)||quantity<1||quantity>10000)throw new Error('INVALID_QUANTITY');const lines=[['equipment-rental',base.rentalCents],['annual-subscription',base.annualCents]].map(([sku,unit])=>{const originalCents=unit*quantity;const netCents=Math.round(originalCents*bps/10000);return {sku,quantity,originalCents,discountCents:originalCents-netCents,netCents}});return {currency:'USD',code,payBasisPoints:bps,lines,originalCents:lines.reduce((s,l)=>s+l.originalCents,0),discountCents:lines.reduce((s,l)=>s+l.discountCents,0),productCents:lines.reduce((s,l)=>s+l.netCents,0),taxCents:null,shippingCents:null,status:'ESTIMATE_ONLY'};}
function commission({paidProductCents,refundedProductCents=0,commissionBasisPoints}){if(![paidProductCents,refundedProductCents,commissionBasisPoints].every(Number.isSafeInteger)||paidProductCents<0||refundedProductCents<0||refundedProductCents>paidProductCents||commissionBasisPoints<0||commissionBasisPoints>10000)throw new Error('INVALID_COMMISSION');return Math.round((paidProductCents-refundedProductCents)*commissionBasisPoints/10000)}
function qualifyReferral({registry,requested,existing,now=Date.now(),explicit=false}){const find=code=>registry.find(a=>a.id===code&&a.status==='ACTIVE');if(explicit&&find(requested))return {dealerId:requested,expiresAt:now+30*86400000,origin:'explicit'};if(existing&&existing.expiresAt>now&&find(existing.dealerId))return existing;if(find(requested))return {dealerId:requested,expiresAt:now+30*86400000,origin:'first-valid'};return null}
const api={quote,commission,qualifyReferral,codes,base};if(typeof module==='object'&&module.exports)module.exports=api;else root.QuickMindCommerce=api;
})(globalThis);
